<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { listProjectTasks } from '@/features/projects/api'
import { extractAssetWorkspace, generateAssetImages, generateAssetPrompts, getAssetWorkspace, getLocalizedStoryboard, type AssetWorkspaceEntity, type AssetWorkspaceRead, type LocalizedStoryboardRead } from '@/features/projects/replicaFiveStep'
import type { TaskRead } from '@/features/projects/types'

const route=useRoute(), projectId=computed(()=>String(route.params.id??'')), episodeId=computed(()=>String(route.query.episode??'')), episodeOrder=computed(()=>Number(route.query.ep??1)||1)
const workspace=ref<AssetWorkspaceRead|null>(null), localized=ref<LocalizedStoryboardRead|null>(null), activeTask=ref<TaskRead|null>(null)
const selectedIds=ref<string[]>([]), detailId=ref(''), filter=ref<'ALL'|'CHARACTER'|'SCENE'|'PROP'>('ALL'), action=ref(''), error=ref(''), message=ref('')
let timer:number|undefined
const content=computed(()=>workspace.value?.content??null), running=computed(()=>activeTask.value?.status==='queued'||activeTask.value?.status==='running')
const episodeEntityIds=computed(()=>{if(!episodeId.value||!localized.value?.content)return null;const ids=new Set<string>();localized.value.content.shots.filter(s=>s.episode_id===episodeId.value).forEach(s=>{s.target_character_ids.forEach(id=>ids.add(id));s.target_scene_ids.forEach(id=>ids.add(id));s.target_prop_ids.forEach(id=>ids.add(id))});return ids})
const assets=computed(()=>(content.value?.assets??[]).filter(a=>episodeEntityIds.value===null||episodeEntityIds.value.has(a.target_entity_id)))
const filtered=computed(()=>assets.value.filter(a=>filter.value==='ALL'||a.asset_type===filter.value)), selected=computed(()=>assets.value.filter(a=>selectedIds.value.includes(a.target_asset_id))), selectedWithPrompt=computed(()=>selected.value.filter(a=>Boolean(a.image_prompt))), detail=computed(()=>assets.value.find(a=>a.target_asset_id===detailId.value)??null)
const counts=computed(()=>({ALL:assets.value.length,CHARACTER:assets.value.filter(x=>x.asset_type==='CHARACTER').length,SCENE:assets.value.filter(x=>x.asset_type==='SCENE').length,PROP:assets.value.filter(x=>x.asset_type==='PROP').length}))
const label=(t:string)=>t==='CHARACTER'?'人物':t==='SCENE'?'场景':'道具'
const activeMedia=(a:AssetWorkspaceEntity)=>a.generations.find(x=>x.generation_id===a.active_generation_id)?.reference_media??[]
const cardStatus=(a:AssetWorkspaceEntity)=>a.image_status==='GENERATING'?'正在生成图片…':a.image_status==='QUEUED'?'图片排队中':a.prompt_status==='GENERATING'?'正在生成提示词…':a.prompt_status==='QUEUED'?'提示词排队中':a.image_status==='FAILED'||a.prompt_status==='FAILED'?'生成失败':a.image_prompt?'提示词已就绪':'等待生成提示词'
const processing=(a:AssetWorkspaceEntity)=>['QUEUED','GENERATING'].includes(a.prompt_status)||['QUEUED','GENERATING'].includes(a.image_status)
const toggle=(id:string)=>{selectedIds.value=selectedIds.value.includes(id)?selectedIds.value.filter(x=>x!==id):[...selectedIds.value,id]}
const selectFiltered=()=>{const ids=filtered.value.map(x=>x.target_asset_id);selectedIds.value=ids.every(id=>selectedIds.value.includes(id))?selectedIds.value.filter(id=>!ids.includes(id)):[...new Set([...selectedIds.value,...ids])]}
async function refresh(silent=false){try{const [w,l,t]=await Promise.all([getAssetWorkspace(projectId.value),getLocalizedStoryboard(projectId.value),listProjectTasks(projectId.value)]);workspace.value=w;localized.value=l;activeTask.value=[...t.filter(x=>['replica.asset-images','replica.asset-prompts'].includes(x.task_type??''))].sort((a,b)=>+new Date(b.created_at)-+new Date(a.created_at))[0]??null}catch(exc){if(!silent)error.value=exc instanceof Error?exc.message:'读取视觉资产工作台失败'}}
async function extract(){action.value='extract';error.value='';try{workspace.value=await extractAssetWorkspace(projectId.value);message.value='已提取本土化分镜中的人物、场景和道具。'}catch(exc){error.value=exc instanceof Error?exc.message:'提取资产失败'}finally{action.value=''}}
async function start(kind:'prompts'|'images'){const ids=kind==='prompts'?selectedIds.value:selectedWithPrompt.value.map(x=>x.target_asset_id);if(!ids.length){error.value=kind==='prompts'?'请先选择资产。':'请选择已有提示词的资产。';return}action.value=kind;error.value='';try{activeTask.value=kind==='prompts'?await generateAssetPrompts(projectId.value,ids):await generateAssetImages(projectId.value,ids);message.value=kind==='prompts'?`已将 ${ids.length} 个资产加入顺序提示词队列。`:`已将 ${ids.length} 个资产加入顺序生成队列。`}catch(exc){error.value=exc instanceof Error?exc.message:'启动任务失败'}finally{action.value=''}}
onMounted(()=>{void refresh();timer=window.setInterval(()=>void refresh(true),1500)});onBeforeUnmount(()=>{if(timer!==undefined)window.clearInterval(timer)})
</script>

<template><section class="workspace" data-testid="asset-images-workspace">
<header><div><h2>视觉资产</h2><p>第 {{ episodeOrder }} 集 · 提取后可单选或多选，分步生成提示词和图片</p></div><span v-if="content">{{ assets.length }} 个资产</span></header>
<p v-if="error" class="notice error">{{ error }}</p><p v-if="message" class="notice success">{{ message }}</p>
<section v-if="running&&activeTask" class="queue" data-testid="asset-images-progress"><div><strong>{{ activeTask.task_type==='replica.asset-prompts'?'提示词队列正在执行':'图片队列正在执行' }}</strong><span>一次只生成一个，完成后自动回填并处理下一个。</span></div><b>{{ activeTask.progress_percent }}%</b><i><em :style="{width:`${activeTask.progress_percent}%`}"/></i></section>
<section v-if="!content" class="blank"><div>◇</div><h3>还没有提取视觉资产</h3><p>只提取本土化分镜实际出现的人物、场景和道具，不会立即请求模型。</p><button :disabled="action==='extract'" @click="extract">{{ action==='extract'?'提取中…':'提取资产' }}</button></section>
<template v-else><nav><div class="filters"><button v-for="item in (['ALL','CHARACTER','SCENE','PROP'] as const)" :key="item" :class="{active:filter===item}" @click="filter=item">{{ item==='ALL'?'全部':label(item) }} {{ counts[item] }}</button></div><div class="actions"><button class="ghost" @click="selectFiltered">全选当前分类</button><span>已选 {{ selected.length }}</span><button :disabled="running||!selected.length" @click="start('prompts')">生成提示词</button><button :disabled="running||!selectedWithPrompt.length" @click="start('images')">生成图片</button></div></nav>
<div class="grid"><article v-for="asset in filtered" :key="asset.target_asset_id" :class="{selected:selectedIds.includes(asset.target_asset_id),processing:processing(asset)}"><button class="check" :aria-label="`选择 ${asset.display_name}`" @click="toggle(asset.target_asset_id)">{{ selectedIds.includes(asset.target_asset_id)?'✓':'' }}</button><button class="preview" @click="detailId=asset.target_asset_id"><img v-if="activeMedia(asset)[0]" :src="activeMedia(asset)[0].uri"/><span v-if="!activeMedia(asset).length||processing(asset)" class="preview-status">{{ cardStatus(asset) }}</span><span v-else class="image-ready">已出图</span><i v-if="processing(asset)"/></button><div class="copy"><div class="asset-title"><small>{{ label(asset.asset_type) }}</small><strong>{{ asset.display_name }}</strong></div><p>{{ asset.review_description_zh }}</p><footer><span :class="{ready:asset.prompt_status==='READY'}">{{ asset.prompt_status==='READY'?'提示词已生成':cardStatus(asset) }}</span><span :class="{ready:activeMedia(asset).length}">{{ activeMedia(asset).length?`图片记录 ${asset.generations.length} 次`:'未生成图片' }}</span></footer></div></article></div>
<div v-if="detail" class="mask" @click.self="detailId=''" ><aside><header><div><small>{{ label(detail.asset_type) }}</small><h3>{{ detail.display_name }}</h3></div><button @click="detailId=''">×</button></header><main><p v-if="detail.last_error" class="notice error">{{ detail.last_error }}</p><section><h4>视觉定义</h4><p>{{ detail.review_description_zh }}</p></section><section v-if="detail.asset_type==='CHARACTER'&&detail.character_visual_design"><h4>角色视觉设计</h4><p><b>身份：</b>{{ detail.character_visual_design.identity_summary }}</p><p><b>脸部：</b>{{ detail.character_visual_design.face_design }}</p><p><b>发型：</b>{{ detail.character_visual_design.hair_design }}</p><p><b>体态：</b>{{ detail.character_visual_design.body_design }}</p><p><b>服装：</b>{{ detail.character_visual_design.wardrobe_design }}</p><p><b>风格：</b>{{ detail.character_visual_design.style_direction }}</p><p v-if="detail.character_visual_design.signature_features.length"><b>识别点：</b>{{ detail.character_visual_design.signature_features.join('；') }}</p><p v-if="detail.character_visual_design.continuity_rules.length"><b>一致性锁：</b>{{ detail.character_visual_design.continuity_rules.join('；') }}</p><small v-if="detail.character_visual_skill_id">{{ detail.character_visual_skill_id }}@{{ detail.character_visual_skill_version }}</small></section><section><h4>模型专属提示词</h4><p v-if="detail.prompt_review_zh">{{ detail.prompt_review_zh }}</p><pre v-if="detail.image_prompt">{{ detail.image_prompt }}</pre><p v-else>选择后点击“生成提示词”。</p><small v-if="detail.prompt_skill_id">{{ detail.prompt_skill_id }}@{{ detail.prompt_skill_version }} · {{ detail.prompt_contract }}</small></section><section><h4>生成历史</h4><p v-if="!detail.generations.length">还没有生成图片。</p><div v-for="(g,i) in [...detail.generations].reverse()" :key="g.generation_id" class="history"><b>第 {{ detail.generations.length-i }} 次生成</b><time>{{ new Date(g.created_at).toLocaleString() }}</time><div><img v-for="m in g.reference_media" :key="m.reference_id" :src="m.uri"/></div><em v-if="g.generation_id===detail.active_generation_id">当前采用</em></div></section></main></aside></div></template>
</section></template>

<style scoped>
.workspace{display:grid;gap:14px;color:#182642}.workspace>header,nav,.actions,.filters{display:flex;align-items:center;justify-content:space-between;gap:9px;flex-wrap:wrap}.workspace>header{padding-bottom:12px;border-bottom:1px solid #e6e9f0}h2,h3,h4,p{margin:0}header p{margin-top:4px;color:#7c8799;font-size:11px}header>span{padding:5px 8px;border-radius:99px;background:#f0edff;color:#654fe5;font-size:10px}.notice{padding:9px 11px;border-radius:8px;font-size:12px}.error{background:#fff1ef;color:#a33b32}.success{background:#edf9f0;color:#2d7140}.blank{display:grid;justify-items:center;gap:12px;padding:90px 24px;border:1px dashed #d7dbe5;border-radius:14px;background:#fff;text-align:center}.blank>div{display:grid;place-items:center;width:58px;height:58px;border-radius:18px;background:#f0edff;color:#6751e7;font-size:26px}.blank p{color:#7b8495;font-size:12px}.blank button,.actions button:not(.ghost){min-height:35px;padding:0 14px;border:0;border-radius:8px;background:#654ce6;color:#fff;font-size:11px;font-weight:750}.queue{display:grid;grid-template-columns:1fr auto;gap:8px;padding:13px 15px;border:1px solid #ded9fa;border-radius:11px;background:#faf9ff}.queue div{display:grid}.queue span{color:#747083;font-size:11px}.queue i{grid-column:1/-1;height:6px;background:#e8e5f4}.queue em{display:block;height:100%;background:#6551e5}.filters button,.ghost{min-height:32px;padding:0 10px;border:1px solid #e0e3ea;border-radius:7px;background:#fff;color:#66728a}.filters button.active{border-color:#7660eb;background:#f0edff;color:#5c46dc}.actions span{font-size:11px}.actions button:disabled{opacity:.45}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.grid article{position:relative;display:grid;grid-template-rows:200px minmax(112px,auto);min-width:0;overflow:hidden;border:1px solid #dfe3eb;border-radius:12px;background:#fff;box-shadow:0 3px 10px rgba(31,43,69,.035);transition:border-color .15s ease,box-shadow .15s ease,transform .15s ease}.grid article:hover{border-color:#cfd4e0;box-shadow:0 8px 20px rgba(31,43,69,.08);transform:translateY(-1px)}.grid article.selected{border-color:#725bea;box-shadow:0 0 0 2px #eeeaff}.check{position:absolute;z-index:3;top:10px;left:10px;display:grid;width:27px;height:27px;place-items:center;padding:0;border:1px solid #cbd1dc;border-radius:8px;background:#fffffff2;color:#654ce6;font-weight:900;box-shadow:0 2px 7px #18203420;cursor:pointer}.grid article.selected .check{border-color:#684fe8;background:#684fe8;color:#fff}.preview{position:relative;display:grid;width:100%;height:200px;place-items:center;overflow:hidden;padding:0;border:0;border-bottom:1px solid #e6e9ef;background:#f0f2f5;color:#7d8798;cursor:pointer}.preview img{grid-area:1/1;width:100%;height:100%;object-fit:contain}.preview-status{grid-area:1/1;z-index:1;padding:6px 9px;border-radius:7px;background:#ffffffe8;box-shadow:0 2px 8px #18203418;font-size:11px}.image-ready{position:absolute;z-index:2;right:9px;bottom:9px;padding:4px 7px;border-radius:999px;background:#236b3ce6;color:#fff;font-size:9px;font-weight:800}.copy{display:grid;align-content:start;gap:8px;min-width:0;padding:12px 13px}.asset-title{display:grid!important;grid-template-columns:auto minmax(0,1fr);align-items:start;gap:8px!important;min-width:0}.copy small{flex:none;padding-top:2px;color:#b75d18;font-size:10px;white-space:nowrap}.copy strong{min-width:0;overflow:hidden;color:#1c2b46;font-size:14px;line-height:1.25;text-overflow:ellipsis;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2}.copy p{overflow:hidden;color:#657188;font-size:10px;line-height:1.55;text-overflow:ellipsis;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2}.copy footer{display:flex;align-self:end;gap:5px;flex-wrap:wrap}.copy footer span{padding:3px 6px;border-radius:5px;background:#f2f3f6;color:#8992a2;font-size:9px}.copy footer .ready{background:#eaf7ee;color:#2c8249}.mask{position:fixed;z-index:80;inset:56px 0 0;background:#181d2820}.mask aside{position:absolute;right:0;width:min(540px,94vw);height:100%;overflow:auto;background:#fff;box-shadow:-14px 0 38px #1820342e}.mask aside>header{display:flex;justify-content:space-between;padding:18px;border-bottom:1px solid #e7e9ee}.mask header button{border:0;background:none;font-size:24px}.mask main{display:grid;gap:20px;padding:18px}.mask section{display:grid;gap:8px}.mask p,.mask pre{color:#56637a;font-size:11px;line-height:1.7}.mask pre{max-height:240px;overflow:auto;margin:0;padding:10px;background:#f5f4f1;white-space:pre-wrap}.history{position:relative;display:grid;gap:7px;padding:10px;border:1px solid #e2e5eb;border-radius:9px}.history time{font-size:9px}.history img{width:100px;height:100px;object-fit:contain}.history em{position:absolute;right:8px;padding:2px 5px;background:#e9f7ed;color:#2f7e48;font-size:8px}@media(max-width:1100px){.grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:760px){.grid{grid-template-columns:repeat(2,1fr)}nav{align-items:stretch;flex-direction:column}}@media(max-width:520px){.grid{grid-template-columns:1fr}}
.preview i{position:absolute;right:0;bottom:0;left:0;height:3px;overflow:hidden;background:#ded9fa}.preview i:after{display:block;width:40%;height:100%;content:"";background:#6a52e7;animation:asset-working 1.1s linear infinite}.processing{border-color:#c9c0fa!important}@keyframes asset-working{from{transform:translateX(-100%)}to{transform:translateX(350%)}}
</style>
